/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, DMP, Mul, Pow, QQ, Rational, RecurrenceOperator, RecurrenceOperatorAlgebra, Sym, ZZ, add, isUnsolved, pow, rational } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.holonomic.recurrence", () => {
  it("RecurrenceOperator([0, 1, n**2], R)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(new RecurrenceOperator([0, 1, pow(n, Rational.of(2n, 1n, { gcd: 1n }))], new RecurrenceOperatorAlgebra(ZZ.oldPolyRing(n), 'Sn')))).toBe('(1)Sn + (n**2)Sn**2');
  });
  it("Sn*n", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(new RecurrenceOperator([Rational.of(0n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })], new RecurrenceOperatorAlgebra(ZZ.oldPolyRing(n), 'Sn')).mul(n))).toBe('(n + 1)Sn');
  });
  it("n*Sn*n + 1 - Sn**2*n", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(new RecurrenceOperator([Rational.of(1n, 1n, { gcd: 1n }), add(n, pow(n, Rational.of(2n, 1n, { gcd: 1n })))], new RecurrenceOperatorAlgebra(ZZ.oldPolyRing(n), 'Sn')).sub(new RecurrenceOperator([Rational.of(0n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), add(Rational.of(2n, 1n, { gcd: 1n }), n)], new RecurrenceOperatorAlgebra(ZZ.oldPolyRing(n), 'Sn'))))).toBe('(1) + (n**2 + n)Sn + (-n - 2)Sn**2');
  });
  // the arguments do not type-check against the public API
  //   R
  //   => Univariate Recurrence Operator Algebra in intermediate Sn over the base ring ZZ[n]
  it.todo("R");
});

